// One folder per run so concurrent submissions never collide.
const runId = ($json.submittedAt || String(Date.now())).replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/concat-${runId}`;

const binKeys = Object.keys($input.item.binary || {});
if (binKeys.length < 2) {
  throw new Error(`Need at least 2 video clips to combine - got ${binKeys.length}. Select multiple files in the Video Clips field.`);
}

// "1080x1920 (vertical / Shorts, TikTok)" -> 1080, 1920
const formatLabel = $json['Output Format'] || '1920x1080 (landscape / YouTube)';
const dimsMatch = formatLabel.match(/(\d+)x(\d+)/);
if (!dimsMatch) throw new Error(`Could not read dimensions from "${formatLabel}".`);
const width = Number(dimsMatch[1]);
const height = Number(dimsMatch[2]);

// Order = the order the files were selected in the form - this is the concat order.
const clips = binKeys.map((key, i) => ({ key, index: i, clipPath: `${dir}/clip-${i}.mp4` }));

return {
  json: { ...$json, dir, outputPath: `${dir}/combined.mp4`, width, height, clips },
  binary: $input.item.binary,
};

// Create the temp folder (Execute Command) wipes json + binary - re-attach both
// from Prepare Run so the uploaded clips survive to the split/write step.
const run = $('Prepare Run').item.json;
return { json: run, binary: $('Prepare Run').item.binary };

// One item per clip, each carrying just its own binary - lets the next node
// (Read/Write File) write every clip to disk in a single pass over N items.
const run = $('Prepare Run').item.json;
const binary = $('Prepare Run').item.binary;
return run.clips.map(c => ({
  json: { index: c.index, clipPath: c.clipPath },
  binary: { clip: binary[c.key] },
}));

// Ignores the N items from the write step (their own output is just file
// metadata) and rebuilds the command from Prepare Run's deterministic clip list -
// this only needs to run once no matter how many clips there are.
const run = $('Prepare Run').item.json;
const { clips, width, height, outputPath } = run;

// concat FILTER, not the concat DEMUXER: clips can differ in resolution, aspect
// ratio, frame rate or audio format and this still produces a clean, in-sync
// output. Each clip is scaled to fit inside the target frame (letterboxed, not
// cropped or stretched) and its audio is reformatted to a common rate/layout
// before the concat filter joins everything.
let inputs = '';
let filterParts = '';
let joinParts = '';
clips.forEach((c, i) => {
  inputs += `-i "${c.clipPath}" `;
  filterParts += `[${i}:v]scale=${width}:${height}:force_original_aspect_ratio=decrease,pad=${width}:${height}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,fps=30,format=yuv420p[v${i}];`;
  filterParts += `[${i}:a]aformat=sample_rates=44100:channel_layouts=stereo[a${i}];`;
  joinParts += `[v${i}][a${i}]`;
});
const filterComplex = `${filterParts}${joinParts}concat=n=${clips.length}:v=1:a=1[outv][outa]`;
const command = `ffmpeg -y ${inputs}-filter_complex "${filterComplex}" -map "[outv]" -map "[outa]" -c:v libx264 -c:a aac -movflags +faststart "${outputPath}"`;

return [{ json: { command, outputPath, clipCount: clips.length, width, height } }];

const cmdResult = $json;
const plan = $('Build the FFmpeg command').item.json;
if (cmdResult.exitCode !== undefined && cmdResult.exitCode !== 0) {
  throw new Error('FFmpeg failed: ' + (cmdResult.stderr || '').slice(-800));
}
return {
  json: {
    outputPath: plan.outputPath,
    clipCount: plan.clipCount,
    width: plan.width,
    height: plan.height,
  },
};

// Read/Write File's read operation replaces json with file metadata only -
// merge the combine report back in so the output has both the numbers and the file.
const report = $('Verify the combine succeeded').item.json;
return { json: { ...report, file: $json }, binary: $input.item.binary };
